pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    assert_eq!(condition.len(), arr.len());

    // Pre-allocate exactly the number of `true` entries to ensure
    // result length matches the count of `true` values.
    let true_count = condition.iter().filter(|&&b| b).count();
    let mut result = Vec::with_capacity(true_count);

    for (keep, value) in condition.into_iter().zip(arr.into_iter()) {
        if keep {
            result.push(value);
        }
    }

    debug_assert_eq!(result.len(), true_count);
    result
}